    const findingId = result.findings[0]!.id;
    // First hop: synthetic root cause → FailedMount event node
    const hop1 = causesEdges.find(
      (e) => e.source.startsWith('finding:missing-secret:') && e.target.startsWith('event:FailedMount:'),
