// ---------------------------------------------------------------------------
// Fixtures — missing Secret
// ---------------------------------------------------------------------------

const missingSecretPod: K8sResource = {
  apiVersion: 'v1',
  kind: 'Pod',
  metadata: { name: 'secret-pod', namespace: 'production' },
  spec: {
    containers: [
      {
        name: 'app',
        image: 'myapp:v2.0.0',
        envFrom: [{ secretRef: { name: 'app-credentials' } }],
      },
    ],
  },
  status: { phase: 'Pending' },
